// Reader of the versioned market-regime reference (market-regime-reference-v1.json, generated by
// tools/market-regime-reference.mjs from the market-regime study's CI output). Pure functions of the reference
// object: no percentage is typed here, and nothing changes a rule, threshold or verdict. The study is index-level
// (^GSPC / ^IXIC daily bars), never a stock's value, and every share is P(21-session drawdown <= -5%) of one state.
const finite = Number.isFinite;

export const REFERENCE_SCHEMA = 'market-regime-reference-v1';
export const INDEX_SYMBOLS = Object.freeze(['^GSPC', '^IXIC']);
const LABELS = new Set(['robust', 'weak', 'unstable', 'insufficient']);
/** 〔偏り〕: a state whose sessions lie 60% or more, or 40% or less, in the study's first half (findings-final.md). */
export const BIAS_SHARE = Object.freeze({ atLeast: 60, atMost: 40 });
export const TAGS = Object.freeze({
  both: '〔S&P・Nasdaqとも〕', '^GSPC': '〔S&Pのみ〕', '^IXIC': '〔Nasdaqのみ〕', unestablished: '〔未確立〕', insufficient: '〔標本不足〕', bias: '〔偏り〕', breadth: '〔参考〕',
});
const other = symbol => (symbol === '^GSPC' ? '^IXIC' : '^GSPC');
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const share = value => value === null || (finite(value) && value >= 0 && value <= 100);

/** A reference the market tab may read: its schema, methods, buckets and every state's fields in shape. */
export function validReference(ref) {
  if (!plain(ref) || ref.schema_version !== REFERENCE_SCHEMA || typeof ref.study_version !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(ref.study_as_of || '')) return false;
  if (typeof ref.methods?.distribution !== 'string' || typeof ref.methods?.followThrough !== 'string') return false;
  if (ref.outcome?.horizonSessions !== 21 || ref.outcome?.drawdownPercent !== -5) return false;
  const b = ref.buckets;
  if (!plain(b) || !Array.isArray(b.ddGrades) || !finite(b.ddWarn) || !finite(b.nearHighPercent) || !finite(b.ftdRecentSessions) || !plain(b.states)) return false;
  if (!INDEX_SYMBOLS.every(symbol => typeof ref.samples?.[symbol]?.first === 'string' && typeof ref.samples[symbol].last === 'string')) return false;
  if (!plain(ref.indicators) || !plain(ref.breadth)) return false;
  for (const indicator of Object.values(ref.indicators)) {
    if (!plain(indicator?.states)) return false;
    for (const state of Object.values(indicator.states)) {
      if (!plain(state) || !LABELS.has(state.labelDd5) || !LABELS.has(state.labelMean) || !share(state.pDd5) || !share(state.comparatorPDd5) || !share(state.firstHalfShare)) return false;
      if (!['baseline', 'other_state'].includes(state.comparator)) return false;
    }
  }
  return Object.values(ref.breadth).every(rule => plain(rule) && LABELS.has(rule.labelDd5) && LABELS.has(rule.labelMean));
}

export const referenceState = (ref, key, state) => ref?.indicators?.[key]?.states?.[state] ?? null;

/**
 * The tag of one index's state, from its own label and the other index's label for the same state: robust on
 * both 〔S&P・Nasdaqとも〕, robust on this index only 〔S&Pのみ〕/〔Nasdaqのみ〕, not established here 〔未確立〕
 * (weak or unstable), too few sessions 〔標本不足〕. A state robust only on the other index is not established here.
 */
export function stateTag(ref, suffix, symbol, state) {
  const own = referenceState(ref, `${symbol}.${suffix}`, state);
  if (!own) return null;
  if (own.labelDd5 === 'robust') return referenceState(ref, `${other(symbol)}.${suffix}`, state)?.labelDd5 === 'robust' ? TAGS.both : TAGS[symbol];
  return own.labelDd5 === 'insufficient' ? TAGS.insufficient : TAGS.unestablished;
}
export const biasTag = entry => finite(entry?.firstHalfShare) && (entry.firstHalfShare >= BIAS_SHARE.atLeast || entry.firstHalfShare <= BIAS_SHARE.atMost) ? TAGS.bias : null;

/** The warning summary's checks (marketCardView keys) and the study indicator each one is. */
export const SIGNAL_INDICATORS = Object.freeze({
  'dist-S&P': Object.freeze({ symbol: '^GSPC', suffix: 'dd.binary', state: 'warn', method: 'distribution' }),
  'dist-NAS': Object.freeze({ symbol: '^IXIC', suffix: 'dd.binary', state: 'warn', method: 'distribution' }),
  'ftd-S&P': Object.freeze({ symbol: '^GSPC', suffix: 'ftd.state', state: 'ftd_failed', method: 'followThrough' }),
  'ftd-NAS': Object.freeze({ symbol: '^IXIC', suffix: 'ftd.state', state: 'ftd_failed', method: 'followThrough' }),
  split: Object.freeze({ breadth: 'rule.split' }), lows: Object.freeze({ breadth: 'rule.lows' }), template: Object.freeze({ breadth: 'rule.template' }),
  stage: Object.freeze({ breadth: 'rule.stage' }), leaders: Object.freeze({ breadth: 'rule.leaders' }), breakout: Object.freeze({ breadth: 'rule.breakout' }),
});
/**
 * A fired check's tag. Breadth checks are 〔参考〕 (the 2021-26 breadth panel was consistent with chance as a
 * whole); an index check takes its state's tag, and none when the published method differs from the study's.
 * `methods` holds the published method ids of the check's index ({ distribution, followThrough }).
 */
export function signalTag(ref, key, methods = {}) {
  const map = SIGNAL_INDICATORS[key];
  if (!ref || !map) return null;
  if (map.breadth) return ref.breadth?.[map.breadth] ? TAGS.breadth : null;
  if (!methods[map.method] || methods[map.method] !== ref.methods?.[map.method]) return null;
  return stateTag(ref, map.suffix, map.symbol, map.state);
}

// ---- states, judged as the study judged them --------------------------------------------------------------
/** The 50/200-day cell (study ma.quadrant): both distances known, above means strictly above. */
export function quadrantState(summary) {
  if (!summary || !finite(summary.vsMa) || !finite(summary.vs200)) return null;
  return summary.vs200 > 0 ? (summary.vsMa > 0 ? 'above_both' : 'above200_below50') : (summary.vsMa > 0 ? 'below200_above50' : 'below_both');
}
/** Within nearHighPercent of the 252-session closing high (study high.near), only with a full year of closes. */
export const highState = (summary, nearHighPercent) => summary?.fullYear === true && finite(summary.fromHigh) && finite(nearHighPercent) ? (summary.fromHigh >= -nearHighPercent ? 'near' : 'below') : null;
/** The distribution-day grade (study dd.graded) of a whole count. */
export function ddGradeState(count, ref) {
  if (!Number.isSafeInteger(count) || count < 0) return null;
  const at = ref.buckets.ddGrades.findIndex(([low, high]) => count >= low && (high === null || count <= high));
  return at >= 0 ? ref.buckets.states['dd.graded']?.[at] ?? null : null;
}
/** The follow-through bucket (study ftd.state): a window that opens on the peak is its own state (判定保留). */
export const ftdState = ft => ft?.available === true && typeof ft.state === 'string' ? (ft.state === 'no_correction' && ft.peakAtWindowStart === true ? 'no_correction_pending' : ft.state) : null;
/** FTD confirmed at most ftdRecentSessions sessions ago (study combo.ftd_recent's first state). */
export const ftdRecent = (ft, ref) => ft?.available === true && ft.state === 'confirmed' && Number.isSafeInteger(ft.ftd?.sessionsSince) && ft.ftd.sessionsSince <= ref.buckets.ftdRecentSessions;

/** The study's index sample, as years for the summary and as dates for the source line. */
export function referencePeriod(ref) {
  const firsts = INDEX_SYMBOLS.map(symbol => ref.samples[symbol].first), lasts = INDEX_SYMBOLS.map(symbol => ref.samples[symbol].last);
  const first = firsts.reduce((a, b) => (a < b ? a : b)), last = lasts.reduce((a, b) => (a > b ? a : b));
  return { first, last, fromYear: first.slice(0, 4), toYear: last.slice(0, 4), same: firsts[0] === firsts[1] && lasts[0] === lasts[1] };
}
